LayoutBuilder(builder: (context, constraints) {
  final hinges = MediaQuery.of(context).displayFeatures.where(
    (f) => f.type == DisplayFeatureType.hinge &&
      f.bounds.height > f.bounds.width && f.bounds.width > 0).toList();
  if (constraints.maxWidth < 720) return buildStacked();
  if (hinges.isNotEmpty) {
    final gap = hinges.first.bounds;
    return Row(children: [
      SizedBox(width: gap.left, child: buildList()),
      SizedBox(width: gap.width), Expanded(child: buildDetail()),
    ]);
  }
  return Row(children: [Expanded(child: buildList()), Expanded(child: buildDetail())]);
});
